def terrain(x):
 if x<2.506:return 0.
 if x>4:return 1.
 return .5+(x-3.3)*np.tan(.5)+.1/np.cos(.5)
def smooth(t):return t*t*(3-2*t)

def generate(s,dx=.25,sw=.5,ds=.25,nsteps=14):
 c=Controller(s);feet=c.feet.copy();base=c.base.copy();acts=[]
 def step(base,ft,con=(1,1)):
  pitch=[-.5 if 2.53<f[0]<3.95 else 0 for f in ft]
  a=c.step(base,ft,con,footpitch=pitch);s.step(a);acts.append(a)
 def shift(target,N,con=(1,1),endfeet=None):
  nonlocal base,feet
  old=base.copy();f0=feet.copy()
  for k in range(N):
   u=smooth((k+1)/N);base=old*(1-u)+target*u
   if endfeet is not None:feet=f0*(1-u)+endfeet*u
   step(base,feet,con)
 for _ in range(30):step(base,feet)
